Data: A prompt (prompt) and a secret key $\mathsf{\vphantom{p}sk}$
Result: Watermarked text $x$
1 $x\leftarrow\overline{\mathsf{Model}}(\textsc{prompt})$;
2 if $H_{e}(\mathsf{Model},\textsc{prompt},x)>6\lambda$ then
3 while $F_{\mathsf{\vphantom{p}sk}}(x)\neq 0^{b}$ or $H_{e}(\mathsf{Model},\textsc{prompt},x)\leq 6\lambda$ do
4 $x\leftarrow\overline{\mathsf{Model}}(\textsc{prompt})$;
5 end while
6 end if
7 return x;

Data: A prompt (prompt) and a secret key $\mathsf{\vphantom{p}sk}$
Result: Watermarked text $x_{1},\ldots,x_{L}$
1 $i\leftarrow 1$;
2 $H\leftarrow 0$;
3 while $\texttt{done}\notin(x_{1},\ldots,x_{i-1})$ do
4 $p_{i}\leftarrow\mathsf{Model}(\textsc{prompt},x_{1},\ldots,x_{i-1})$;
5 if $H<\lambda$ then
// Collect more internal entropy
6 Sample $x_{i}\leftarrow p_{i}$;
7 $H\leftarrow H-\log p_{i}(x_{i})$;
8 if $H\geq\lambda$ then
9 $r\leftarrow(x_{1},\dots,x_{i})$;
10 end if
11 else
// Embed the watermark
12 $x_{i}\leftarrow\mathbbm{1}[F_{\mathsf{\vphantom{p}sk}}(r,i)\leq p_{i}(1)]$;
13 end if
14 $i\leftarrow i+1$;
15 end while

Data: Text $x_{1},\ldots,x_{L}$ and a secret key $\mathsf{\vphantom{p}sk}$
Result: $\mathsf{true}$ or $\mathsf{false}$
1 for $i\in[L]$ do
2 $r^{(i)}\leftarrow(x_{1},\ldots,x_{i})$;
3 Define $v^{(i)}_{j}:=x_{j}\cdot F_{\mathsf{\vphantom{p}sk}}(r^{(i)},j)+(1-x_{j})\cdot(1-F_{\mathsf{\vphantom{p}sk}}(r^{(i)},j))$ for $j\in[L]$;
4 if $\sum_{j=i+1}^{L}\ln(1/v^{(i)}_j)>(L-i)+\lambda\sqrt{L-i}$ then
5 return $\mathsf{true}$;
6 end if
7 end for
8 return $\mathsf{false}$;

Data: A prompt (prompt), secret key $\mathsf{\vphantom{p}sk}$, and parameter $\lambda$
Result: Watermarked text $x_{1},\ldots,x_{L}$
1 $r\leftarrow\bot,H\leftarrow 0,i\leftarrow 1,\ell\leftarrow 0$;
2 while $\texttt{done}\notin(x_{1},\ldots,x_{i-1})$ do
3 $p_{i}\leftarrow\mathsf{Model}(\textsc{prompt},x_{1},\ldots,x_{i-1})$;
4 if $r=\bot$ then
// Still sampling the first block
5 Sample $x_{i}\leftarrow p_{i}$;
6 else
// Embed the watermark
7 $x_{i}\leftarrow\mathbbm{1}[F_{\mathsf{\vphantom{p}sk}}(r,i)\leq p_{i}(1)]$;
8 $H\leftarrow H-\log p_{i}(x_{i})$;
9 if $H\geq\frac{2}{\ln 2}\lambda\sqrt{\ell}$ then
// Reassign $r$
10 $r\leftarrow(x_{i-\ell},\dots,x_{i})$;
11 $H\leftarrow 0,\ell\leftarrow 0$;
12 end if
13 $i\leftarrow i+1,\ell\leftarrow\ell+1$;
14 end while

Data: Text $x_{1},\ldots,x_{L}$ and a secret key $\mathsf{\vphantom{p}sk}$
Result: $\mathsf{true}$ or $\mathsf{false}$
1 for $i,\ell\in[L]$, $\ell<i$ do
2 $r^{(i,\ell)}\leftarrow(x_{i-\ell},\ldots,x_{i})$;
3 $v_{j}^{(i,\ell)}\leftarrow x_{j}\cdot F_{\mathsf{\vphantom{p}sk}}(r^{(i,\ell)},j)+(1-x_{j})\cdot(1-F_{\mathsf{\vphantom{p}sk}}(r^{(i,\ell)},j))$ for each $j\in[L]$;
4 for $k\in[i+1,L]$ do
5 if $\sum_{j=i+1}^{k}\ln(1/v_j^{(i,\ell)})>(k-i)+\lambda\sqrt{k-i}$ then
6 return $\mathsf{true}$;
7 end if
8 end for
9 end for
10 return $\mathsf{false}$;
